    fornecedor_nome text NOT NULL,
    fornecedor_cnpj text,
    previsao_entrega date,
    frete numeric(18,2) DEFAULT 0 NOT NULL,
    outras_despesas numeric(18,2) DEFAULT 0 NOT NULL,
    parcelas jsonb DEFAULT '[]'::jsonb NOT NULL,
